// behaviour test for 0x00F2D6E0 CScriptDef::Transfer: the 944 statements of the row run against a recording model of the persist
// context.  Checked statement by statement against the RETAIL order (generated from the retail disassembly, not from the source):
// the key string retail pushes, the member engine/CScriptDef.h places at the offset retail pushes, and the kind of the retail
// callee (long / float / CDefString / CCharString / the four vectors / the five sub-component vectors).  Also: 944 transfers
// over 943 distinct members (TemplePrayerFactorHighest twice, statements 478 and 479), every member reset to its type's default
// in clear mode, and a save / load round trip that restores every member.
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#include <map>
#include <set>

enum EKind {
    K_LONG, K_FLOAT, K_DEFSTRING, K_CHARSTRING,
    K_VECTOR_CHARSTRING, K_VECTOR_FLOAT, K_VECTOR_LONG, K_VECTOR_DEFSTRING,
    K_SUB_CCONVERSATION, K_SUB_CFIREHEARTPATTERNDEF, K_SUB_CFEATDEF, K_SUB_CARENAROUNDDEF, K_SUB_CHEROSOULSROUNDDEF
};

// ---- model value types ----
struct CDefString { long TablePos; CDefString() : TablePos(-1) {} };
struct CCharString { std::string Text; };
struct CConversation { long Tag; CConversation() : Tag(0) {} };
struct CFireHeartPatternDef { long Tag; CFireHeartPatternDef() : Tag(0) {} };
struct CFeatDef { long Tag; CFeatDef() : Tag(0) {} };
struct CArenaRoundDef { long Tag; CArenaRoundDef() : Tag(0) {} };
struct CHeroSoulsRoundDef { long Tag; CHeroSoulsRoundDef() : Tag(0) {} };

static int KindOf(long*) { return K_LONG; }
static int KindOf(float*) { return K_FLOAT; }
static int KindOf(CDefString*) { return K_DEFSTRING; }
static int KindOf(CCharString*) { return K_CHARSTRING; }
static int VectorKindOf(CCharString*) { return K_VECTOR_CHARSTRING; }
static int VectorKindOf(float*) { return K_VECTOR_FLOAT; }
static int VectorKindOf(long*) { return K_VECTOR_LONG; }
static int VectorKindOf(CDefString*) { return K_VECTOR_DEFSTRING; }
static int SubKindOf(CConversation*) { return K_SUB_CCONVERSATION; }
static int SubKindOf(CFireHeartPatternDef*) { return K_SUB_CFIREHEARTPATTERNDEF; }
static int SubKindOf(CFeatDef*) { return K_SUB_CFEATDEF; }
static int SubKindOf(CArenaRoundDef*) { return K_SUB_CARENAROUNDDEF; }
static int SubKindOf(CHeroSoulsRoundDef*) { return K_SUB_CHEROSOULSROUNDDEF; }

// ---- a flat byte image of one value (save / load) ----
static void Put(std::string& s, const long& v) { s.append((const char*)&v, sizeof v); }
static void Put(std::string& s, const float& v) { s.append((const char*)&v, sizeof v); }
static void Put(std::string& s, const CDefString& v) { Put(s, v.TablePos); }
static void Put(std::string& s, const CCharString& v) { long n = (long)v.Text.size(); Put(s, n); s += v.Text; }
static void Put(std::string& s, const CConversation& v) { Put(s, v.Tag); }
static void Put(std::string& s, const CFireHeartPatternDef& v) { Put(s, v.Tag); }
static void Put(std::string& s, const CFeatDef& v) { Put(s, v.Tag); }
static void Put(std::string& s, const CArenaRoundDef& v) { Put(s, v.Tag); }
static void Put(std::string& s, const CHeroSoulsRoundDef& v) { Put(s, v.Tag); }
template <class T> static void Put(std::string& s, const std::vector<T>& v)
{
    long n = (long)v.size(); Put(s, n);
    for (long i = 0; i < n; i++) Put(s, v[i]);
}
static void Get(const std::string& s, size_t& at, long& v) { std::memcpy(&v, s.data() + at, sizeof v); at += sizeof v; }
static void Get(const std::string& s, size_t& at, float& v) { std::memcpy(&v, s.data() + at, sizeof v); at += sizeof v; }
static void Get(const std::string& s, size_t& at, CDefString& v) { Get(s, at, v.TablePos); }
static void Get(const std::string& s, size_t& at, CCharString& v) { long n; Get(s, at, n); v.Text = s.substr(at, (size_t)n); at += (size_t)n; }
static void Get(const std::string& s, size_t& at, CConversation& v) { Get(s, at, v.Tag); }
static void Get(const std::string& s, size_t& at, CFireHeartPatternDef& v) { Get(s, at, v.Tag); }
static void Get(const std::string& s, size_t& at, CFeatDef& v) { Get(s, at, v.Tag); }
static void Get(const std::string& s, size_t& at, CArenaRoundDef& v) { Get(s, at, v.Tag); }
static void Get(const std::string& s, size_t& at, CHeroSoulsRoundDef& v) { Get(s, at, v.Tag); }
template <class T> static void Get(const std::string& s, size_t& at, std::vector<T>& v)
{
    long n; Get(s, at, n); v.clear();
    for (long i = 0; i < n; i++) { T item; Get(s, at, item); v.push_back(item); }
}

// ---- the recording persist context ----
template <class T> struct CPersistTraits { T DefaultVal; CPersistTraits() : DefaultVal() {} ~CPersistTraits() {} };
struct SEvent { std::string Name; const void* Member; int Kind; };

class CPersistContext {
public:
    enum { MODE_CLEAR, MODE_SAVE, MODE_LOAD };
    int Mode;
    std::vector<SEvent> Events;
    std::map<std::string, std::string> Store;

    explicit CPersistContext(int mode) : Mode(mode) {}
    void Note(const char* name, const void* member, int kind)
    {
        SEvent e; e.Name = name; e.Member = member; e.Kind = kind; Events.push_back(e);
    }
    template <class T> void Move(const char* name, T& value, const T& defaultVal)
    {
        if (Mode == MODE_CLEAR) value = defaultVal;
        else if (Mode == MODE_SAVE) { std::string s; Put(s, value); Store[name] = s; }
        else { size_t at = 0; Get(Store[name], at, value); }
    }
    template <class T> static T GetDefaultVal(T*) { CPersistTraits<T> traits; return traits.DefaultVal; }
    template <class T> void Transfer(const char* name, T& value, const T& defaultVal)
    {
        Note(name, &value, KindOf(&value)); Move(name, value, defaultVal);
    }
    template <class T> void Transfer(const char* name, T& value) { Transfer(name, value, GetDefaultVal((T*)0)); }
    template <class T> void TransferVector(const char* name, std::vector<T>& value)
    {
        Note(name, &value, VectorKindOf((T*)0)); Move(name, value, std::vector<T>());
    }
    template <class T> void TransferVectorOfSubComponents(const char* name, std::vector<T>& value)
    {
        Note(name, &value, SubKindOf((T*)0)); Move(name, value, std::vector<T>());
    }
};

